import{t as e}from"./utils-COoNfFoj.js";var t={slug:`jasmine-nove`,influencerName:`Jasmine Nove`,influencerHandle:`@novemediaco`,influencerAvatarUrl:`${e}/jasmine-nove-avatar.png`,heroDescription:`I built this planning system with Perplexity Computer using only prompts. It now handles content strategy for my agency and all my clients. Try it yourself below.`,assetTitle:`Personal Creator OS`,screenshotUrl:`${e}/jasmine-nove.png`,remixUrl:`https://www.perplexity.ai/computer/a/nove-os-0YHbPHjjTpqE6fUBpCLffg`,promptTitle:`Try Jas' prompt`,promptText:`Build a single-creator content-planning web app: 4-step onboarding (handle → niche → audience → loading) using preset tiles plus an "OTHER" tile that expands inline with a tip and autofocused custom input, then a home page with an audience-aware daily hook (copyable, mark-posted toggle), a 30-day plan, a hook bank with category filters and live search, a daily tracker with streak and monthly stats starting at zero, and a profile page with edit and reset actions. Use Express + Vite + React + Tailwind + SQLite via Drizzle, hash-based routing, lowercase casual copy with no emojis, and a data-testid on every interactive element. Before publishing, click-test every button, card, link, and CTA via Playwright across all pages — remove anything non-functional, ensure React hooks are called before early returns, and return a short summary of what was tested, fixed, and removed.`};export{t as default};
